  initHotKeys(...rest: any[]): any {
    let ctrl = this;
    Promise.resolve(this.translate.get(['widget.undo', 'widget.save', 'widget.saveAs', 'widget.toggle-fullscreen', 'widget.run']).toPromise()).then((translations?: any) => {
        hotkeys.bindTo(this)
            .add({
                combo: 'ctrl+q',
                description: translations['widget.undo'],
                allowIn: ['INPUT', 'SELECT', 'TEXTAREA'],
                callback: (event?: any, ...rest: any[]) => {
                    if (!this.undoDisabled()) {
                        event.preventDefault();
                        this.undoWidget();
                    }
                }
            })
            .add({
                combo: 'ctrl+s',
                description: translations['widget.save'],
                allowIn: ['INPUT', 'SELECT', 'TEXTAREA'],
                callback: (event?: any, ...rest: any[]) => {
                    if (!this.saveDisabled()) {
                        event.preventDefault();
                        this.saveWidget();
                    }
                }
            })
            .add({
                combo: 'shift+ctrl+s',
                description: translations['widget.saveAs'],
                allowIn: ['INPUT', 'SELECT', 'TEXTAREA'],
                callback: (event?: any, ...rest: any[]) => {
                    if (!this.saveAsDisabled()) {
                        event.preventDefault();
                        this.saveWidgetAs();
                    }
                }
            })
            .add({
                combo: 'shift+ctrl+f',
                description: translations['widget.toggle-fullscreen'],
                allowIn: ['INPUT', 'SELECT', 'TEXTAREA'],
                callback: (event?: any, ...rest: any[]) => {
                    event.preventDefault();
                    this.toggleFullscreen();
                }
            })
            .add({
                combo: 'ctrl+enter',
                description: translations['widget.run'],
                allowIn: ['INPUT', 'SELECT', 'TEXTAREA'],
                callback: (event?: any, ...rest: any[]) => {
                    event.preventDefault();
                    this.applyWidgetScript();
                }
        });
    });
  }
